class Bookstore:
    def __init__(self):
        """
        Initializes the inventory as an empty dictionary.
        """
        self.inventory = {}

    def add_book(self, isbn, quantity):
        """
        Adds the specified quantity of the book with the given ISBN to the inventory.
        If the book already exists, updates its quantity.

        :param isbn: str, the ISBN number of the book
        :param quantity: int, the quantity of the book to add
        """
        if isbn in self.inventory:
            self.inventory[isbn] += quantity
        else:
            self.inventory[isbn] = quantity

    def remove_book(self, isbn, quantity):
        """
        Removes the specified quantity of the book with the given ISBN from the inventory.

        :param isbn: str, the ISBN number of the book
        :param quantity: int, the quantity of the book to remove
        :return: bool, True if the book was successfully removed, False otherwise
        """
        if isbn not in self.inventory or self.inventory[isbn] < quantity:
            return False
        else:
            self.inventory[isbn] -= quantity
            if self.inventory[isbn] == 0:
                del self.inventory[isbn]
            return True

    def get_inventory(self):
        """
        Returns a copy of the current inventory dictionary.

        :return: dict, a copy of the inventory
        """
        return self.inventory.copy()
