class LibraryManagementSystem:
    def __init__(self):
        """Initialize an empty list to store book details."""
        self.books = []

    def add_book(self, title, author, isbn):
        """Adds a book to the library with the given title, author, and ISBN."""
        book = {'title': title, 'author': author, 'isbn': isbn}
        self.books.append(book)
        print(f"Book added: {title} by {author}, ISBN: {isbn}")

    def remove_book(self, isbn):
        """Removes a book from the library by its ISBN. Prints an error message if the book does not exist."""
        initial_count = len(self.books)
        self.books = [book for book in self.books if book['isbn'] != isbn]
        if len(self.books) == initial_count:
            print(f"Error: Book with ISBN {isbn} not found.")
        else:
            print(f"Book removed with ISBN: {isbn}")

    def list_books(self):
        """Lists all books in the library. Prints a message if the library is empty."""
        if not self.books:
            print("No books in the library.")
        else:
            print("Library Catalogue:")
            for book in self.books:
                print(f"Title: {book['title']}, Author: {book['author']}, ISBN: {book['isbn']}")
