def count_elements(lst):
    """
    Returns a dictionary where keys are unique elements from the list and values are lists of indices
    where each element appears in the original list.

    :param lst: List of integers
    :return: Dictionary with elements as keys and lists of indices as values
    """
    index_dict = {}
    for index, element in enumerate(lst):
        if element not in index_dict:
            index_dict[element] = [index]
        else:
            index_dict[element].append(index)
