def extract_strings(data):
    """
    Traverse a nested dictionary and extract all string values into a list.

    :param data: A dictionary representing a JSON-like data structure.
    :return: A list of all string values found in the dictionary.
    """
    string_values = []

    def traverse(d):
        if isinstance(d, dict):
            for key, value in d.items():
                traverse(value)
        elif isinstance(d, list):
            for item in d:
                traverse(item)
        elif isinstance(d, str):
            string_values.append(d)

    traverse(data)
    return string_values

# Example usage:
