def count_string_frequencies(strings):
    """
    Counts the frequency of each string in the given list and returns a dictionary
    with strings as keys and their frequencies as values.

    :param strings: List of strings
    :return: Dictionary with string frequencies
    """
    frequency_dict = {}
    for string in strings:
        if string in frequency_dict:
            frequency_dict[string] += 1
        else:
            frequency_dict[string] = 1
    return frequency_dict

