import string
from datetime import date, timedelta

class RandomDataGenerator:

    @staticmethod
    def generate_random_integer(start=0, end=100):
        """
        Generates a random integer within the specified range [start, end].
        If no range is provided, generates between 0 and 100 by default.
        """
        return random.randint(start, end)

    @staticmethod
    def generate_random_float(start=0.0, end=1.0):
        """
        Generates a random floating-point number within the specified range [start, end).
        If no range is provided, generates between 0.0 and 1.0 by default.
        """
        return random.uniform(start, end)

    @staticmethod
    def generate_random_string(length=10, characters=string.ascii_letters + string.digits):
        """
        Generates a random string of specified length using the given character set.
        By default, generates a 10-character string using alphanumeric characters.
        """
        return ''.join(random.choice(characters) for _ in range(length))

    @staticmethod
    def generate_random_date(start_date=date.today() - timedelta(days=365), end_date=date.today()):
        """
        Generates a random date between start_date and end_date, inclusive.
        By default, generates a date within the last year.
        """
        delta = end_date - start_date
        random_days = random.randint(0, delta.days)
        return start_date + timedelta(days=random_days)
