import math

def distance(point1, point2):
    """
    Calculate the Euclidean distance between two points.

    :param point1: A tuple (x1, y1) representing the first point.
    :param point2: A tuple (x2, y2) representing the second point.
    :return: The Euclidean distance between point1 and point2.
    """
    return math.sqrt((point1[0] - point2[0]) ** 2 + (point1[1] - point2[1]) ** 2)

def point_line_distance(point, start, end):
    """
    Calculate the perpendicular distance from a point to a line segment.

    :param point: A tuple (x, y) representing the point.
    :param start: A tuple (x1, y1) representing the start point of the line segment.
    :param end: A tuple (x2, y2) representing the end point of the line segment.
    :return: The perpendicular distance from the point to the line segment.
    """
    if start == end:
        return distance(point, start)

    line_length = distance(start, end)
    if line_length == 0:
        return distance(point, start)

    x_diff = end[0] - start[0]
    y_diff = end[1] - start[1]

    u = ((point[0] - start[0]) * x_diff + (point[1] - start[1]) * y_diff) / (line_length ** 2)

    if u < 0:
        return distance(point, start)
    elif u > 1:
        return distance(point, end)
    else:
        closest_point = (start[0] + u * x_diff, start[1] + u * y_diff)
        return distance(point, closest_point)

def douglas_peucker(points, epsilon):
    """
    Recursively apply the Douglas-Peucker algorithm to simplify a path.

    :param points: A list of tuples representing the path.
    :param epsilon: The tolerance for simplification.
    :return: A list of tuples representing the simplified path.
    """
    dmax = 0.0
    index = 0

    for i in range(1, len(points) - 1):
        d = point_line_distance(points[i], points[0], points[-1])
        if d > dmax:
            index = i
            dmax = d

    if dmax > epsilon:
        recursively_simplified_1 = douglas_peucker(points[:index + 1], epsilon)
        recursively_simplified_2 = douglas_peucker(points[index:], epsilon)
        return recursively_simplified_1[:-1] + recursively_simplified_2
    else:
        return [points[0], points[-1]]

def optimize_path(path, epsilon=0.1):
    """
    Optimize a path using the Douglas-Peucker algorithm.

    :param path: A list of tuples representing the path.
    :param epsilon: The tolerance for simplification (default is 0.1).
    :return: A list of tuples representing the optimized path.
    """
    if len(path) < 2:
        return path

    return douglas_peucker(path, epsilon)
```

