def determine_winner(player_a_choice, player_b_choice):
    """
    Determines the winner of a game of Rock, Paper, Scissors, Lizard, Spock.

    Args:
        player_a_choice (str): The choice of player A ('r', 'p', 's', 'l', or 'sp').
        player_b_choice (str): The choice of player B ('r', 'p', 's', 'l', or 'sp').

    Returns:
        bool or None: True if player A wins, False if player B wins, None if it's a tie.

    Raises:
        ValueError: If either input is not one of the valid choices.
    """
    valid_choices = {'r', 'p', 's', 'l', 'sp'}

    if player_a_choice not in valid_choices or player_b_choice not in valid_choices:
        raise ValueError("Invalid input. Please enter 'r', 'p', 's', 'l', or 'sp'.")

    winning_conditions = {
        'r': {'s', 'l'},
        'p': {'r', 'sp'},
        's': {'p', 'l'},
        'l': {'p', 'sp'},
        'sp': {'s', 'r'}
    }

    if player_a_choice == player_b_choice:
        return None
    elif player_b_choice in winning_conditions[player_a_choice]:
        return True
    else:
        return False
```

