def validate_phone_number(s):
    """
    Validates if the given string s is a valid phone number in the format (123) 456-7890.

    Parameters:
    s (str): The string to be validated.

    Returns:
    bool: True if s is a valid phone number, False otherwise.
    """
    if len(s) != 14:
        return False

    if s[0] != '(' or s[4] != ')' or s[5] != ' ' or s[9] != '-':
        return False

    for i in range(14):
        if i in [0, 4, 5, 9]:
            continue
        if not ('0' <= s[i] <= '9'):
            return False

    return True
