def group_by_sign(numbers):
    """
    Groups the given list of integers into positive, negative, and zero categories.

    Parameters:
    numbers (list of int): The list of integers to be categorized.

    Returns:
    dict: A dictionary with keys 'positive', 'negative', and 'zero', each mapping to a list of integers.
    """
    grouped_numbers = {'positive': [], 'negative': [], 'zero': []}
    for number in numbers:
        if number > 0:
            grouped_numbers['positive'].append(number)
        elif number < 0:
            grouped_numbers['negative'].append(number)
        else:
            grouped_numbers['zero'].append(number)
    return grouped_numbers

