def calculate_winning_percentage(tournaments, player_name):
    """
    Calculate the winning percentage of a player across all tournaments.

    :param tournaments: List of tournaments, where each tournament is a list of matches.
    :param player_name: Name of the player whose winning percentage is to be calculated.
    :return: Winning percentage of the player rounded to two decimal places.
    """
    total_matches = 0
    matches_won = 0

    for tournament in tournaments:
        for match in tournament:
            total_matches += 1
            if match['player_a'] == player_name and match['a_score'] > match['b_score']:
                matches_won += 1
            elif match['player_b'] == player_name and match['b_score'] > match['a_score']:
                matches_won += 1

    if total_matches == 0:
        return 0.00

    winning_percentage = (matches_won / total_matches) * 100
    return round(winning_percentage, 2)
