class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class SinglyLinkedList:
    def __init__(self):
        self.head = None

    def add_node(self, data):
        """Adds a new node with the given data at the end of the list."""
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        last_node = self.head
        while last_node.next:
            last_node = last_node.next
        last_node.next = new_node

    def remove_node(self, key):
        """Removes the first node with the specified key from the list."""
        current_node = self.head
        prev_node = None
        while current_node and current_node.data != key:
            prev_node = current_node
            current_node = current_node.next
        if current_node is None:
            return  # Key not found in the list
        if prev_node is None:
            self.head = current_node.next  # Removing the head node
        else:
            prev_node.next = current_node.next

    def display(self):
        """Prints the elements of the list in order, separated by ' -> '."""
        current_node = self.head
        elements = []
        while current_node:
            elements.append(current_node.data)
            current_node = current_node.next
        print(" -> ".join(map(str, elements)) if elements else "")
