def path_formatter(path: str, os_type: str, style: str) -> str:
    """
    Formats a given file or directory path according to the specified operating system and style.

    Parameters:
    - path (str): The file or directory path to be formatted.
    - os_type (str): The operating system type, either "Windows" or "Unix".
    - style (str): The desired path style, either "trailing" or "leading".

    Returns:
    - str: The formatted path.

    Raises:
    - ValueError: If os_type or style is not one of the expected values.
    """
    if not path:
        return ""

    if os_type == "Windows":
        separator = '\\'
        normalized_path = path.replace('/', '\\')
    elif os_type == "Unix":
        separator = '/'
        normalized_path = path.replace('\\', '/')
    else:
        raise ValueError("os_type must be either 'Windows' or 'Unix'")

    if style == "trailing":
        if not normalized_path.endswith(separator):
            normalized_path += separator
    elif style == "leading":
        if not normalized_path.startswith(separator):
            normalized_path = separator + normalized_path
    else:
        raise ValueError("style must be either 'trailing' or 'leading'")

    return normalized_path
```

