class WeatherAnalyzer:
    def __init__(self, weather_records):
        self.records = weather_records

    def average_temperature(self):
        """
        Returns the average temperature of all the records.
        """
        if not self.records:
            return 0.0
        return sum(record['temperature'] for record in self.records) / len(self.records)

    def average_humidity(self):
        """
        Returns the average humidity of all the records.
        """
        if not self.records:
            return 0.0
        return sum(record['humidity'] for record in self.records) / len(self.records)

    def coldest_day(self):
        """
        Returns the date of the coldest day.
        """
        if not self.records:
            return None
        coldest = min(self.records, key=lambda record: record['temperature'])
        return coldest['date']

    def hottest_day(self):
        """
        Returns the date of the hottest day.
        """
        if not self.records:
            return None
        hottest = max(self.records, key=lambda record: record['temperature'])
        return hottest['date']
