    """Prompts user to enter rock, paper, or scissors."""
    while True:
        user_input = input("Enter your choice (rock, paper, scissors): ").strip().lower()
        if user_input in ['rock', 'paper', 'scissors']:
            return user_input
        print("Invalid choice. Please try again.")

def determine_winner(user_choice, computer_choice):
    """Determines the winner of a single round of rock-paper-scissors."""
    if user_choice == computer_choice:
        return "draw"
    if (user_choice == 'rock' and computer_choice == 'scissors') or \
       (user_choice == 'scissors' and computer_choice == 'paper') or \
       (user_choice == 'paper' and computer_choice == 'rock'):
        return "user"
    return "computer"

def play_game(rounds):
    """Plays a series of rock-paper-scissors rounds against the computer."""
    user_score = 0
    computer_score = 0

