def sum_prime_numbers(limit):
    """
    Computes the sum of all prime numbers up to and including the given limit.

    :param limit: An integer representing the upper bound for the range of numbers to consider.
    :return: An integer representing the sum of all prime numbers up to and including the limit.
    """
    if limit < 2:
        return 0

    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False

    for num in range(2, int(limit**0.5) + 1):
        if sieve[num]:
            for multiple in range(num*num, limit + 1, num):
                sieve[multiple] = False

    return sum(index for index, is_prime in enumerate(sieve) if is_prime)
