def find_first_missing_positive(nums):
    """
    Finds the smallest positive integer missing from the list.

    :param nums: List[int] - The list of integers.
    :return: int - The smallest missing positive integer.
    """
    n = len(nums)

    for i in range(n):
        if nums[i] <= 0:
            nums[i] = n + 1

    for i in range(n):
        num = abs(nums[i])
        if num <= n:
            if nums[num - 1] > 0:
                nums[num - 1] *= -1

    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1

