def reverse_rec_sum(int_list):
    """
    Recursively reverses a list of integers and returns the sum of the elements in the reversed list.

    Parameters:
    int_list (list): A list of integers to be reversed and summed.

    Returns:
    int: The sum of the elements in the reversed list.

    Raises:
    ValueError: If the input list is None.
    """
    if int_list is None:
        raise ValueError("Input list is None")

    def reverse_and_sum(lst, index, reversed_list, current_sum):
        if index < 0:
            return current_sum
        else:
            element = lst[index]
            reversed_list.append(element)
            return reverse_and_sum(lst, index - 1, reversed_list, current_sum + element)

    return reverse_and_sum(int_list, len(int_list) - 1, [], 0)
