from typing import Any, List, Dict

class Graph:
    def __init__(self):
        self.adjacency_list: Dict[Any, Dict[Any, int]] = {}

    def add_node(self, node: Any):
        """Adds a node to the graph."""
        if node not in self.adjacency_list:
            self.adjacency_list[node] = {}

    def add_edge(self, node1: Any, node2: Any, weight: int = 1):
        """Adds an undirected edge between node1 and node2 with the given weight."""
        if node1 not in self.adjacency_list:
            self.add_node(node1)
        if node2 not in self.adjacency_list:
            self.add_node(node2)
        self.adjacency_list[node1][node2] = weight
        self.adjacency_list[node2][node1] = weight

    def remove_node(self, node: Any):
        """Removes a node and all its edges from the graph."""
        if node in self.adjacency_list:
            for neighbor in self.adjacency_list[node]:
                self.adjacency_list[neighbor].pop(node)
            del self.adjacency_list[node]

    def remove_edge(self, node1: Any, node2: Any):
        """Removes the edge between node1 and node2."""
        if node1 in self.adjacency_list and node2 in self.adjacency_list[node1]:
            del self.adjacency_list[node1][node2]
        if node2 in self.adjacency_list and node1 in self.adjacency_list[node2]:
            del self.adjacency_list[node2][node1]

    def get_neighbors(self, node: Any) -> List[Any]:
        """Returns a list of neighbors for a given node."""
        if node in self.adjacency_list:
            return list(self.adjacency_list[node].keys())
        return []

    def get_weight(self, node1: Any, node2: Any) -> int:
        """Returns the weight of the edge between node1 and node2. Returns 0 if no edge exists."""
        if node1 in self.adjacency_list and node2 in self.adjacency_list[node1]:
            return self.adjacency_list[node1][node2]
        return 0
