def flatten_and_convert(input_list):
    """
    Processes a list of tuples and returns a new list where each tuple is replaced by a single integer
    if all elements in the tuple are the same, otherwise by the string "Mixed".

    Raises a RuntimeError if the input is not a list or if the list contains non-tuple elements.
    """
    if not isinstance(input_list, list):
        raise RuntimeError("Input must be a list.")

    result = []

    for item in input_list:
        if not isinstance(item, tuple):
            raise RuntimeError("All elements in the input list must be tuples.")

        if len(item) == 0:
            result.append("Mixed")
            continue

        first_element = item[0]
        all_same = True
        i = 1
        while i < len(item):
            if item[i] != first_element:
                all_same = False
                break
            i += 1

        if all_same:
            result.append(first_element)
        else:
            result.append("Mixed")

    return result
