def extract_keys(data, keys):
    """
    Recursively extracts specified keys from a nested dictionary or list.

    :param data: The nested dictionary or list to search.
    :param keys: A list of keys to extract.
    :return: A dictionary containing the extracted keys and their values.
    """
    metadata = {}
    if isinstance(data, dict):
        for key, value in data.items():
            if key in keys:
                metadata[key] = value
            elif isinstance(value, (dict, list)):
                nested_metadata = extract_keys(value, keys)
                if nested_metadata:
                    metadata.update(nested_metadata)
    elif isinstance(data, list):
        for item in data:
            nested_metadata = extract_keys(item, keys)
            if nested_metadata:
                metadata.update(nested_metadata)
    return metadata

