def find_largest_prime(n):
    """
    Returns the largest prime number less than or equal to n.
    If no prime number exists, returns -1.

    :param n: An integer (1 ≤ n ≤ 10^6)
    :return: The largest prime number less than or equal to n, or -1 if no prime number exists.
    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    for candidate in range(n, 1, -1):
        if is_prime(candidate):
            return candidate
    return -1

