class Matrix:
    def __init__(self, data):
        """
        Initialize the Matrix with a 2D list.

        :param data: List of lists representing the matrix.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def __add__(self, other):
        """
        Add two matrices of the same dimensions.

        :param other: Another Matrix instance.
        :return: A new Matrix instance representing the sum.
        :raises ValueError: If matrices are not of the same dimensions.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to add.")

        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtract two matrices of the same dimensions.

        :param other: Another Matrix instance.
        :return: A new Matrix instance representing the difference.
        :raises ValueError: If matrices are not of the same dimensions.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to subtract.")

        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiply two matrices with compatible dimensions.

        :param other: Another Matrix instance.
        :return: A new Matrix instance representing the product.
        :raises ValueError: If the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if not isinstance(other, Matrix) or self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second matrix.")

        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Return a string representation of the matrix.

        :return: A string with each row on a new line and elements separated by spaces.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
