import json

def extract_values(json_str):
    """
    Parses a JSON string and returns a list of all values in the JSON object.

    :param json_str: A string representing a valid JSON object.
    :return: A list of all values in the JSON object.
    """
    def recursive_extract(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from recursive_extract(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from recursive_extract(item)
        else:
            yield obj

    data = json.loads(json_str)
    return list(recursive_extract(data))
