def infix_to_postfix(expression):
    """
    Convert an infix expression to a postfix expression.

    :param expression: A string representing the infix expression.
    :return: A string representing the postfix expression.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    output = []
    stack = []

    for char in expression:
        if char.isalnum():  # If the character is an operand (letter or digit)
            output.append(char)
        elif char == '(':
            stack.append(char)
        elif char == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()  # pop '('
        else:  # the character is an operator
            while (stack and stack[-1] != '(' and
                   precedence[stack[-1]] >= precedence[char]):
                output.append(stack.pop())
            stack.append(char)

    # pop all the remaining operators from the stack
    while stack:
        output.append(stack.pop())

    return ''.join(output)
