def unique_sum(numbers):
    """
    Calculate the sum of all unique integers in the list using only lists.

    :param numbers: List of integers which may contain duplicates.
    :return: Sum of all unique integers in the list.
    """
    unique_numbers = []
    for number in numbers:
        if number not in unique_numbers:
            unique_numbers.append(number)
    return sum(unique_numbers)
