def count_unique_integers(input_list):
    """
    Returns a list of tuples, where each tuple contains a unique integer from the input list
    and the count of how many times it appears in the list.

    :param input_list: List of integers
    :return: List of tuples (integer, count)
    """
    counts = {}
    for num in input_list:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1
    return list(counts.items())

