def get_device_identifier(device_info: dict) -> str:
    """
    Retrieves a unique identifier from a nested dictionary representing a device's information.
    Searches for the keys "ID_SERIAL_RAW", "ID_SERIAL_SHORT", and "ID_SERIAL" in a depth-first manner.
    Returns the value associated with the first key found, or None if none of these keys exist.

    :param device_info: A dictionary containing the device's information.
    :return: The unique identifier as a string, or None if not found.
    """
    def find_identifier(info):
        for key in ["ID_SERIAL_RAW", "ID_SERIAL_SHORT", "ID_SERIAL"]:
            if key in info:
                return info[key]
        for value in info.values():
            if isinstance(value, dict):
                result = find_identifier(value)
                if result is not None:
                    return result
        return None

    return find_identifier(device_info)
