def find_longest_common_prefix(words):
    """
    Finds the longest common prefix among all strings in the given list.

    :param words: List of strings
    :return: Longest common prefix as a string
    """
    if not words:
        return ""
    if len(words) == 1:
        return words[0]

    prefix = words[0]

    for word in words[1:]:
        if not word:
            return ""
        while not word.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""

    return prefix
```

