class BinaryTreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

    def insert(self, key):
        """Insert a new node with the given key into the BST."""
        if key < self.val:
            if self.left is None:
                self.left = BinaryTreeNode(key)
            else:
                self.left.insert(key)
        else:
            if self.right is None:
                self.right = BinaryTreeNode(key)
            else:
                self.right.insert(key)

    def search(self, key):
        """Return the node with the given key if it exists in the BST, otherwise return None."""
        if self is None or self.val == key:
            return self

        if key > self.val:
            return self.right.search(key) if self.right else None

        return self.left.search(key) if self.left else None

    def delete(self, key):
        """Delete the node with the given key from the BST."""
        if self is None:
            return self

        if key < self.val:
            self.left = self.left.delete(key) if self.left else None

        elif key > self.val:
            self.right = self.right.delete(key) if self.right else None

        else:
            if self.left is None:
                return self.right

            elif self.right is None:
                return self.left

            temp = self.right.min_value_node()
            self.val = temp.val
            self.right = self.right.delete(temp.val)

        return self

    def min_value_node(self):
        """Return the node with the minimum value in the BST."""
        current = self
        while current.left is not None:
            current = current.left
        return current

    def inorder_traversal(self, result=None):
        """Return a list of keys in the BST in in-order traversal order."""
        if result is None:
            result = []
        if self.left:
            self.left.inorder_traversal(result)
        result.append(self.val)
        if self.right:
            self.right.inorder_traversal(result)
        return result
